const MAX = 20 * 1024 * 1024;                      // 코드 — 동작을 정하는 값
const units = await fetch('/data/units.json');      // 데이터 — 큰 표

if (file.size > MAX) {
  status(t('imgresize.err.tooBig', { max: '20MB' })); // 말 묶음 — 사람이 읽는 글
  return;
}

import { t, loadNamespace } from '../../lib/i18n';

// 그리기 전에 그 묶음을 받아 둔다
void loadNamespace('burnnote').then(() => draw(container));

// 글을 꺼낸다
btn.textContent = t('burnnote.btn.copy');

// 기다릴 수 없는 자리(등록 시점)만 기본값을 함께 준다
label: t('burnnote.tab', undefined, '쪽지')

// ✗ 조각내기 — 어순이 다른 언어에서 불가능
el.textContent = t('cart.you_have') + count + t('cart.items');

// ✓ 한 문장 + 자리
el.textContent = t('cart.summary', { n: count });
//   ko: '{n}개 담겼습니다'      en: 'You have {n} items'

// ✓ 개수로 갈리는 말
el.textContent = tn('cart.items', count);
//   ko: { other: '{n}개' }
//   en: { one: '{n} item', other: '{n} items' }

import { t, loadNamespace, loadNamespaces } from '../../lib/i18n';

build(container) {
  void loadNamespace('burnnote').then(() => draw(container));
}

// 여러 묶음이 필요하면
void loadNamespaces('burnnote', 'common').then(() => draw(container));

const KEY = 'kl:mytool:state';

function load(): State {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return DEFAULT;
    return { ...DEFAULT, ...JSON.parse(raw) };   // 옛 판에 없던 항목도 채워진다
  } catch {
    return DEFAULT;                               // 깨진 값이 앱을 멈추게 두지 않는다
  }
}

function save(s: State): void {
  try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* 용량 초과 등 */ }
}

import { isDesktop, invoke } from '../../tauri-bridge';

async function pickFile(): Promise<File | string | null> {
  if (isDesktop()) {
    try { return await invoke<string>('pick_file'); }
    catch { /* 데스크톱인데도 실패 — 아래 웹 방식으로 */ }
  }
  return await pickWithInput();      // 웹에서도 되는 길
}

// 데스크톱에서만 있는 기능이면 단추 자체를 감춘다
if (!isDesktop()) btn.hidden = true;
